<?php
declare(strict_types=1);
namespace SchoolSaaS\Http;
use PDO;
use SchoolSaaS\Auth\Auth;

final class TeacherRouter
{
    public static function dispatch(PDO $db, string $method, string $path): bool
    {
        if (preg_match('#^/api/v1/teacher/(dashboard|profile|classes|students|timetable|attendance|exams|marks|notices|notifications)(?:/([0-9]+)(?:/(read))?)?$#', $path, $m) !== 1) return false;
        $user = Auth::requireUser($db);
        if (!in_array($user['role_name'], ['teacher','school_admin','principal','super_admin'], true)) Response::error('Teacher access required', 'FORBIDDEN', 403);
        $schoolId = (int)$user['school_id']; $isTeacher = $user['role_name'] === 'teacher'; $teacherId = self::teacherId($db, $user, $schoolId); $resource = $m[1]; $id = $m[2] ?? null; $suffix = $m[3] ?? null;
        if ($resource === 'dashboard' && $method === 'GET') {
            $q=$db->prepare('SELECT COUNT(*) FROM timetable_entries WHERE school_id=:school_id AND teacher_id=:teacher_id AND weekday=DAYOFWEEK(CURDATE())-1'); $q->execute(['school_id'=>$schoolId,'teacher_id'=>$teacherId]);
            Response::json(true,'Teacher dashboard loaded',['teacher'=>['name'=>$user['name'],'email'=>$user['email']],'today_classes'=>(int)$q->fetchColumn(),'date'=>date('Y-m-d')]);
        }
        if ($resource === 'profile') {
            if ($method === 'GET') Response::json(true,'Teacher profile loaded',['uuid'=>$user['uuid'],'name'=>$user['name'],'email'=>$user['email'],'role'=>$user['role_name']]);
            if ($method === 'PUT') { $body=self::body(); $name=trim((string)($body['name']??'')); if($name==='') Response::error('name is required','VALIDATION_ERROR',422); $q=$db->prepare('UPDATE users SET name=:name WHERE id=:id AND school_id=:school_id'); $q->execute(['name'=>$name,'id'=>$user['id'],'school_id'=>$schoolId]); Response::json(true,'Profile updated'); }
        }
        if ($resource === 'classes' && $method === 'GET') { $sql=$isTeacher?'SELECT DISTINCT c.id,c.name,c.status FROM classes c JOIN class_subjects cs ON cs.class_id=c.id AND cs.school_id=c.school_id WHERE c.school_id=:school_id AND cs.teacher_id=:teacher_id ORDER BY c.name':'SELECT id,name,status FROM classes WHERE school_id=:school_id ORDER BY name'; $q=$db->prepare($sql); $p=['school_id'=>$schoolId]; if($isTeacher)$p['teacher_id']=$teacherId; $q->execute($p); Response::json(true,'Classes loaded',['items'=>$q->fetchAll()]); }
        if ($resource === 'students' && $method === 'GET') { $sql=$isTeacher?'SELECT DISTINCT s.id,s.uuid,s.admission_no,s.first_name,s.last_name,s.status FROM students s JOIN class_subjects cs ON cs.class_id=s.class_id AND cs.school_id=s.school_id WHERE s.school_id=:school_id AND s.deleted_at IS NULL AND cs.teacher_id=:teacher_id ORDER BY s.first_name,s.last_name':'SELECT id,uuid,admission_no,first_name,last_name,status FROM students WHERE school_id=:school_id AND deleted_at IS NULL ORDER BY first_name,last_name'; $q=$db->prepare($sql); $p=['school_id'=>$schoolId]; if($isTeacher)$p['teacher_id']=$teacherId; $q->execute($p); Response::json(true,'Students loaded',['items'=>$q->fetchAll()]); }
        if ($resource === 'timetable' && $method === 'GET') { $q=$db->prepare('SELECT id,class_id,subject_id,teacher_id,weekday,starts_at,ends_at,room FROM timetable_entries WHERE school_id=:school_id AND teacher_id=:teacher_id ORDER BY weekday,starts_at'); $q->execute(['school_id'=>$schoolId,'teacher_id'=>$teacherId]); Response::json(true,'Timetable loaded',['items'=>$q->fetchAll()]); }
        if($resource === 'attendance') return self::attendance($db,$method,$id,$user,$schoolId,$teacherId,$isTeacher);
        if ($resource === 'exams' && $method === 'GET') { $sql='SELECT e.* FROM exams e WHERE e.school_id=:school_id ORDER BY e.starts_on DESC'; $params=['school_id'=>$schoolId]; if($id){$sql='SELECT e.* FROM exams e WHERE e.school_id=:school_id AND e.id=:id';$params['id']=$id;} $q=$db->prepare($sql);$q->execute($params);Response::json(true,'Exams loaded',$id?($q->fetch()?:[]):['items'=>$q->fetchAll()]); }
        if ($resource === 'marks') return self::marks($db,$method,$id,$user,$schoolId,$teacherId,$isTeacher);
        if ($resource === 'notices' && $method === 'GET') { $q=$db->prepare('SELECT id,uuid,title,body,published_at,status FROM notices WHERE school_id=:school_id AND status="published" ORDER BY published_at DESC LIMIT 50');$q->execute(['school_id'=>$schoolId]);Response::json(true,'Notices loaded',['items'=>$q->fetchAll()]); }
        if ($resource === 'notifications') { if($method==='GET'){ $q=$db->prepare('SELECT id,title,body,read_at,created_at FROM notifications WHERE school_id=:school_id AND (user_id IS NULL OR user_id=:user_id) ORDER BY id DESC LIMIT 50');$q->execute(['school_id'=>$schoolId,'user_id'=>$user['id']]);Response::json(true,'Notifications loaded',['items'=>$q->fetchAll()]); } if($method==='POST'&&$id&&$suffix==='read'){ $q=$db->prepare('UPDATE notifications SET read_at=NOW() WHERE id=:id AND school_id=:school_id AND (user_id IS NULL OR user_id=:user_id)');$q->execute(['id'=>$id,'school_id'=>$schoolId,'user_id'=>$user['id']]);Response::json(true,'Notification marked read');} }
        return false;
    }
    private static function attendance(PDO $db,string $method,?string $id,array $user,int $schoolId,int $teacherId,bool $isTeacher): bool { if($method==='GET'){ $sql='SELECT a.* FROM attendance a WHERE a.school_id=:school_id';$p=['school_id'=>$schoolId];if($isTeacher){$sql.=' AND EXISTS (SELECT 1 FROM students s JOIN class_subjects cs ON cs.class_id=s.class_id AND cs.school_id=s.school_id WHERE s.id=a.student_id AND cs.teacher_id=:teacher_id)';$p['teacher_id']=$teacherId;}if($id){$sql.=' AND a.id=:id';$p['id']=$id;}$sql.=' ORDER BY a.attendance_date DESC';$q=$db->prepare($sql);$q->execute($p);Response::json(true,'Attendance loaded',$id?($q->fetch()?:[]):['items'=>$q->fetchAll()]); } if(in_array($method,['POST','PUT'],true)){ $b=self::body();$student=(int)($b['student_id']??0);$date=trim((string)($b['attendance_date']??''));$status=trim((string)($b['status']??''));if($student<1||$date===''||!in_array($status,['present','absent','late','leave'],true))Response::error('Valid student_id, attendance_date and status are required','VALIDATION_ERROR',422);$checkSql='SELECT s.id FROM students s WHERE s.id=:id AND s.school_id=:school_id AND s.deleted_at IS NULL';$checkParams=['id'=>$student,'school_id'=>$schoolId];if($isTeacher){$checkSql.=' AND EXISTS (SELECT 1 FROM class_subjects cs WHERE cs.class_id=s.class_id AND cs.school_id=s.school_id AND cs.teacher_id=:teacher_id)';$checkParams['teacher_id']=$teacherId;}$check=$db->prepare($checkSql);$check->execute($checkParams);if(!$check->fetchColumn())Response::error('Student is not assigned to this teacher or school','TENANT_REFERENCE_ERROR',422);if($id){$q=$db->prepare('UPDATE attendance SET status=:status,notes=:notes WHERE id=:id AND school_id=:school_id');$q->execute(['status'=>$status,'notes'=>$b['notes']??null,'id'=>$id,'school_id'=>$schoolId]);}else{$q=$db->prepare('INSERT INTO attendance(uuid,school_id,student_id,attendance_date,status,notes,client_uuid) VALUES(:uuid,:school_id,:student,:date,:status,:notes,:client) ON DUPLICATE KEY UPDATE status=VALUES(status),notes=VALUES(notes)');$uuid=self::uuid();$q->execute(['uuid'=>$uuid,'school_id'=>$schoolId,'student'=>$student,'date'=>$date,'status'=>$status,'notes'=>$b['notes']??null,'client'=>$b['client_uuid']??$uuid]);}$db->prepare('INSERT INTO audit_logs(school_id,user_id,action,entity,entity_id) VALUES(:school_id,:user_id,:action,"attendance",:entity_id)')->execute(['school_id'=>$schoolId,'user_id'=>$user['id'],'action'=>$id?'update':'create','entity_id'=>$id??$db->lastInsertId()]);Response::json(true,'Attendance saved');}return false; }
    private static function marks(PDO $db,string $method,?string $id,array $user,int $schoolId,int $teacherId,bool $isTeacher): bool { if($method==='GET'){$sql='SELECT m.* FROM marks m WHERE m.school_id=:school_id';$p=['school_id'=>$schoolId];if($isTeacher){$sql.=' AND EXISTS (SELECT 1 FROM exam_subjects es JOIN class_subjects cs ON cs.subject_id=es.subject_id AND cs.school_id=es.school_id WHERE es.id=m.exam_subject_id AND cs.teacher_id=:teacher_id)';$p['teacher_id']=$teacherId;}$sql.=' ORDER BY m.id DESC';$q=$db->prepare($sql);$q->execute($p);Response::json(true,'Marks loaded',['items'=>$q->fetchAll()]);}if(in_array($method,['POST','PUT'],true)){ $b=self::body();$exam=(int)($b['exam_subject_id']??0);$student=(int)($b['student_id']??0);$marks=(float)($b['marks']??-1);$sql='SELECT es.max_marks FROM exam_subjects es WHERE es.id=:id AND es.school_id=:school_id';$p=['id'=>$exam,'school_id'=>$schoolId];if($isTeacher){$sql.=' AND EXISTS (SELECT 1 FROM class_subjects cs WHERE cs.subject_id=es.subject_id AND cs.school_id=es.school_id AND cs.teacher_id=:teacher_id)';$p['teacher_id']=$teacherId;}$q=$db->prepare($sql);$q->execute($p);$max=$q->fetchColumn();if($max===false||$student<1||$marks<0||$marks>(float)$max)Response::error('Marks are invalid or teacher is not assigned to this subject','VALIDATION_ERROR',422);if($id){$q=$db->prepare('UPDATE marks SET marks=:marks,remarks=:remarks WHERE id=:id AND school_id=:school_id');$q->execute(['marks'=>$marks,'remarks'=>$b['remarks']??null,'id'=>$id,'school_id'=>$schoolId]);}else{$q=$db->prepare('INSERT INTO marks(uuid,school_id,exam_subject_id,student_id,marks,remarks,entered_by) VALUES(:uuid,:school_id,:exam,:student,:marks,:remarks,:entered)');$q->execute(['uuid'=>self::uuid(),'school_id'=>$schoolId,'exam'=>$exam,'student'=>$student,'marks'=>$marks,'remarks'=>$b['remarks']??null,'entered'=>$user['id']]);}Response::json(true,'Marks saved');}return false;}
    private static function teacherId(PDO $db, array $user, int $schoolId): int { $q=$db->prepare('SELECT id FROM teachers WHERE school_id=:school_id AND (user_id=:user_id OR email=:email) ORDER BY user_id IS NULL, id LIMIT 1'); $q->execute(['school_id'=>$schoolId,'user_id'=>$user['id'],'email'=>$user['email']]); $id=$q->fetchColumn(); return $id===false?(int)$user['id']:(int)$id; }
    private static function body(): array { $body=json_decode(file_get_contents('php://input'),true);if(!is_array($body))Response::error('JSON object body is required','VALIDATION_ERROR',422);return $body; }
    private static function uuid(): string { return sprintf('%s-%s-%s-%s-%s',bin2hex(random_bytes(4)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2)),bin2hex(random_bytes(6))); }
}
